1	/// <reference lib="webworker" />
2	declare const self: ServiceWorkerGlobalScope;
3	
4	const CACHE_NAME = "thai-srs-v2";
5	const ASSETS_TO_CACHE = [
6		"/thai-script/",
7		"/thai-script/index.html",
8		"/thai-script/manifest.json",
9		"/thai-script/icons/icon-192x192.png",
10		"/thai-script/icons/icon-512x512.png",
11	];
12	
13	// --- Caching ---
14	
15	self.addEventListener("install", (event) => {
16		event.waitUntil(
17			caches.open(CACHE_NAME).then((cache) => cache.addAll(ASSETS_TO_CACHE)),
18		);
19		self.skipWaiting();
20	});
21	
22	self.addEventListener("activate", (event) => {
23		event.waitUntil(
24			Promise.all([
25				caches
26					.keys()
27					.then((keys) =>
28						Promise.all(
29							keys
30								.filter((key) => key !== CACHE_NAME)
31								.map((key) => caches.delete(key)),
32						),
33					),
34				checkMissedNotification(),
35			]),
36		);
37		self.clients.claim();
38	});
39	
40	self.addEventListener("fetch", (event) => {
41		const { request } = event;
42		if (request.method !== "GET") return;
43	
44		event.respondWith(
45			caches.match(request).then((cached) => {
46				const fetchPromise = fetch(request).then((response) => {
47					if (response.ok) {
48						const clone = response.clone();
49						caches.open(CACHE_NAME).then((cache) => cache.put(request, clone));
50					}
51					return response;
52				});
53				return cached || fetchPromise;
54			}),
55		);
56	});
57	
58	// --- IndexedDB helpers for notification state ---
59	
60	function openDb(): Promise<IDBDatabase> {
61		return new Promise((resolve, reject) => {
62			const request = indexedDB.open("thai-srs-sw", 1);
63			request.onupgradeneeded = () => {
64				request.result.createObjectStore("state");
65			};
66			request.onsuccess = () => resolve(request.result);
67			request.onerror = () => reject(request.error);
68		});
69	}
70	
71	async function getStoredNotification(): Promise<{
72		dueDate: string;
73		cardCount: number;
74	} | null> {
75		const db = await openDb();
76		return new Promise((resolve, reject) => {
77			const tx = db.transaction("state", "readonly");
78			const request = tx.objectStore("state").get("pendingNotification");
79			request.onsuccess = () => resolve(request.result ?? null);
80			request.onerror = () => reject(request.error);
81		});
82	}
83	
84	async function storeNotification(data: {
85		dueDate: string;
86		cardCount: number;
87	}): Promise<void> {
88		const db = await openDb();
89		return new Promise((resolve, reject) => {
90			const tx = db.transaction("state", "readwrite");
91			tx.objectStore("state").put(data, "pendingNotification");
92			tx.oncomplete = () => resolve();
93			tx.onerror = () => reject(tx.error);
94		});
95	}
96	
